CREATE TABLE IF NOT EXISTS globalreach.trade_events (traded_on Date,buyer_id UUID,product_id UUID,hs_code FixedString(6),country_code LowCardinality(String),value_usd Decimal(20,2),quantity Decimal(20,4),weight_kg Decimal(20,4)) ENGINE=MergeTree PARTITION BY toYYYYMM(traded_on) ORDER BY (hs_code,country_code,buyer_id,traded_on);
CREATE MATERIALIZED VIEW IF NOT EXISTS globalreach.buyer_monthly_mv ENGINE=SummingMergeTree PARTITION BY toYYYYMM(month) ORDER BY (buyer_id,month) AS SELECT buyer_id,toStartOfMonth(traded_on) month,sum(value_usd) value_usd,count() shipments FROM globalreach.trade_events GROUP BY buyer_id,month;
CREATE MATERIALIZED VIEW IF NOT EXISTS globalreach.country_product_mv ENGINE=SummingMergeTree PARTITION BY toYYYYMM(month) ORDER BY (country_code,hs_code,month) AS SELECT country_code,hs_code,toStartOfMonth(traded_on) month,sum(value_usd) value_usd,count() shipments FROM globalreach.trade_events GROUP BY country_code,hs_code,month;
